/* =============================================================================
 * malavi.js: the MalAvi site's behavior.
 *
 * Split out of the original single-file design preview. Every figure the page
 * shows is read from assets/data/site_stats.json, which is generated by
 * export/build_site_stats.R from the pinned malaviR release. No count is
 * written into the markup or into this file: bump the release, re-run the
 * export, and the site follows.
 *
 * Loaded as a module, so it is deferred until the DOM is parsed and can use
 * top-level await to fetch its data before rendering.
 * ============================================================================= */

/* GitHub Pages serves these with `Cache-Control: max-age=600`, so a browser will
   happily show a ten-minute-old copy after a publish. The queue and contributor
   board change whenever a submission is processed, not only when the release is
   bumped, so a stale copy is visibly wrong rather than merely out of date.
   `cache: "no-cache"` does NOT disable caching: it forces the browser to
   revalidate with the ETag it already holds, so an unchanged file costs a 304
   and no body transfer. */
const REVALIDATE = { cache: "no-cache" };
const feed = (url) => fetch(url, REVALIDATE).then((r) => r.json());

/* The submission feeds only exist once submissions have been fetched. A missing
   or unreadable feed must not blank the whole page, so each resolves to null and
   the renderers below fall back to an honest "nothing here yet". */
const optional = (url) =>
  fetch(url, REVALIDATE).then((r) => (r.ok ? r.json() : null)).catch(() => null);

/* TABLE_INDEX carries only each table's column spec and row count -- a few KB.
   The rows themselves live in one file per table under assets/data/tables/ and
   are fetched when a visitor actually opens that table, so nobody downloads the
   4 MB hosts table to read the home page. Both are written by
   export/build_tables_json.R. */
/* RESERVED is optional for a reason: it only exists once submissions have been
   fetched, and a page that cannot load it must still answer correctly about the
   release rather than fail. It carries a name and a date per claim, nothing
   more -- see curation/build_name_reservations.py. */
/* BIRDS is the eBird/Clements checklist (export/build_bird_names.R). Optional in
   the same way: without it the name checker still proposes acronyms, it simply
   cannot say whether the host name is a real bird. It is checked against the WHOLE
   checklist, not MalAvi's own hosts -- a parasite sequenced from a bird nobody has
   screened before is exactly the case a new lineage arises from. */
const [STATS, TABLE_INDEX, MAP, REPORTS, QUEUE, CONTRIBUTORS, RESERVED, BIRDS] = await Promise.all([
  feed("assets/data/site_stats.json"),
  feed("assets/data/tables_index.json"),
  feed("assets/data/world_map.json"),
  feed("assets/data/reports.json"),
  optional("assets/data/queue.json"),
  optional("assets/data/contributors.json"),
  optional("assets/data/reserved_names.json"),
  optional("assets/data/bird_names.json")
]);

/* The one sentence every "the checklist does not know this bird" answer ends on.
   Kept in a single place because the name checker gives the same advice whether
   the genus was recognized or not, and the two must not drift apart: the
   checklist is a dated snapshot, so a submitter whose host name is right is told
   to keep the name and flag it on the form rather than change it to match. */
const CHECKLIST_BEHIND_NOTE =
  "If the host species name is correct (perhaps an older or newer name), please " +
  "indicate this on the submission form so that we can try to match the species " +
  "to the current eBird/Clements checklist.";
(function () {
  "use strict";

  /* STATS is the verbatim output of export/build_site_stats.R, which derives every
     figure below from the pinned malaviR release. Nothing on this page is typed in:
     bump the release, re-run the generator, and the whole site follows.
     TABLE_INDEX carries the table column specs; MAP carries the fixed basemap
     shapes and the MalAvi-name -> basemap-name aliases. */

  /* ------------------------------------------------------------------ theme */
  var root = document.documentElement;
  var themeBtn = document.getElementById("themeBtn");
  function prefersDark() {
    return window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches;
  }
  function currentlyDark() {
    var set = root.getAttribute("data-theme");
    return set ? set === "dark" : prefersDark();
  }
  themeBtn.addEventListener("click", function () {
    root.setAttribute("data-theme", currentlyDark() ? "light" : "dark");
    themeBtn.textContent = currentlyDark() ? "Light" : "Dark";
  });
  themeBtn.textContent = currentlyDark() ? "Light" : "Dark";

  /* ------------------------------------------------------------- navigation */
  function show(name) {
    Array.prototype.forEach.call(document.querySelectorAll("#nav button"), function (b) {
      if (b.dataset.view === name) b.setAttribute("aria-current", "page");
      else b.removeAttribute("aria-current");
    });
    Array.prototype.forEach.call(document.querySelectorAll(".view"), function (v) {
      v.classList.toggle("active", v.id === "view-" + name);
    });
    window.scrollTo({ top: 0, behavior: "instant" });
  }
  document.getElementById("nav").addEventListener("click", function (e) {
    var b = e.target.closest("button[data-view]");
    if (b) { location.hash = b.dataset.view; show(b.dataset.view); }
  });

  /* Deep links. Without this the only way into a view is to click its tab, so
     nothing outside the page -- another page, an email, a citation -- can point
     at anything but the home view. The hash is validated against the views that
     actually exist rather than trusted, because it is user-supplied and is used
     to build an element id. */
  function showFromHash() {
    var name = (location.hash || "").replace(/^#/, "");
    if (name && document.getElementById("view-" + name)) show(name);
  }
  window.addEventListener("hashchange", showFromHash);
  showFromHash();
  document.getElementById("brandHome").addEventListener("click", function () { show("home"); });
  document.addEventListener("click", function (e) {
    var g = e.target.closest("[data-goto]");
    if (g) { e.preventDefault(); show(g.dataset.goto); return; }
    var el = e.target.closest("[data-goto-el]");
    if (el) {
      e.preventDefault();
      var target = document.getElementById(el.dataset.gotoEl);
      if (!target) return;
      /* The target can sit in a view that is not on screen: the toolkit links to
         the checker, which lives on the submit page. Switch to its view first,
         or there is nothing on screen to scroll to. */
      var holder = target.closest(".view");
      if (holder && !holder.classList.contains("active")) {
        show(holder.id.replace(/^view-/, ""));
      }
      target.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  });

  /* --------------------------------------------------------------- home viz */

  /* Presentation only: the fixed display order and the color slot each genus
     owns. Every VALUE comes from STATS. Genus order is itself carried in the
     payload, so the colors follow the data rather than a list kept in sync by
     hand. */
  var SLOT = {
    Plasmodium:    { varName: "--g-p", ramp: "p", cls: "sw-p" },
    Haemoproteus:  { varName: "--g-h", ramp: "h", cls: "sw-h" },
    Leucocytozoon: { varName: "--g-l", ramp: "l", cls: "sw-l" }
  };
  var GENERA = STATS.genera.map(function (g) {
    var slot = SLOT[g.key] || { varName: "--ink-3", ramp: "p", cls: "" };
    return {
      key: g.key, varName: slot.varName, ramp: slot.ramp, cls: slot.cls,
      lineages: g.lineages, records: g.records,
      host_species: g.host_species, host_genera: g.host_genera,
      host_families: g.host_families, host_orders: g.host_orders,
      /* Map coverage: countries with records of this genus, and how many of them
         the basemap has a shape for. Both come from the payload -- counting the
         shapes that happened to get shaded would report only the second. */
      map_countries: g.map_countries, map_countries_shown: g.map_countries_shown
    };
  });
  var TOTAL_LINEAGES = STATS.totals.lineages;

  function n(value) { return Number(value).toLocaleString(); }

  /* An older payload has no taxonomy_source; fall back to empty strings so the
     spans render blank rather than "undefined". */
  var TAXONOMY_SOURCE = STATS.taxonomy_source || { clootl_year: "", malaviR_version: "" };

  /* Fill every element that binds to a single figure. */
  function bindStats(mapped, unplaced) {
    var values = {
      release:   STATS.release,
      countries: n(STATS.totals.countries),
      unassigned: n(STATS.unassigned_lineages),
      alnlen:    n(STATS.alignment_length_bp),
      mapped:    n(mapped),
      unplaced:  n(unplaced),
      /* Studies reported only from countries the basemap cannot place. They are
         in the tables but on no panel, so the page says so rather than letting
         them go missing quietly. */
      offmap:    n(STATS.map_studies - STATS.map_studies_shown),
      /* Where the derived host taxonomy key came from. Both move independently
         of the MalAvi release, so the tables page states them. */
      clootl_year:     TAXONOMY_SOURCE.clootl_year,
      malaviR_version: TAXONOMY_SOURCE.malaviR_version
    };
    Array.prototype.forEach.call(document.querySelectorAll("[data-stat]"), function (el) {
      var v = values[el.dataset.stat];
      if (v != null) el.textContent = v;
    });
  }

  /* The headline strip. Labels are presentation; every number is from STATS. */
  var STRIP = [
    ["lineages", "Lineages"], ["host_records", "Host records"],
    ["host_species", "Host species"], ["host_genera", "Host genera"],
    ["host_families", "Host families"], ["host_orders", "Host orders"],
    ["countries", "Countries"], ["references", "References"]
  ];
  function drawStrip() {
    document.getElementById("statStrip").innerHTML = STRIP.map(function (pair) {
      return '<div class="stat"><div class="n display">' + n(STATS.totals[pair[0]]) +
             '</div><div class="k">' + pair[1] + "</div></div>";
    }).join("");
  }

  /* Composition bar + its legend, from the per-genus record counts. */
  function drawComposition() {
    var total = GENERA.reduce(function (s, g) { return s + g.records; }, 0);
    document.getElementById("genusBar").setAttribute("aria-label",
      GENERA.map(function (g) { return g.key + " " + n(g.records) + " records"; }).join("; "));
    document.getElementById("genusBar").innerHTML = GENERA.map(function (g) {
      return '<span style="flex:' + g.records + ';background:var(' + g.varName + ')"></span>';
    }).join("");
    document.getElementById("genusLegend").innerHTML = GENERA.map(function (g) {
      return '<span><i style="background:var(' + g.varName + ')"></i><em class="sci">' +
             g.key + '</em> <span class="mono">' + n(g.records) + "</span> (" +
             Math.round(g.records / total * 100) + "%)</span>";
    }).join("");
    document.getElementById("rankLegend").innerHTML = GENERA.map(function (g) {
      return '<span><i style="background:var(' + g.varName + ')"></i><em class="sci">' +
             g.key + "</em></span>";
    }).join("");
  }

  /* Three dials, each one genus as a share of all lineages. The count is the
     hero; the ring is secondary. Part-to-whole, so a ring is honest here --
     unlike the taxonomic ranks below, where the sets overlap. */
  function drawDonuts() {
    var host = document.getElementById("donuts");
    host.innerHTML = GENERA.map(function (g) {
      var r = 42, c = 2 * Math.PI * r;
      var share = g.lineages / TOTAL_LINEAGES;
      return '<div class="donut">' +
        '<svg width="112" height="112" viewBox="0 0 112 112" role="img" aria-label="' +
          g.key + ": " + g.lineages + " lineages, " + Math.round(share * 100) + '% of all lineages">' +
          '<circle cx="56" cy="56" r="' + r + '" fill="none" stroke="var(--surface-3)" stroke-width="13"/>' +
          '<circle cx="56" cy="56" r="' + r + '" fill="none" stroke="var(' + g.varName + ')" ' +
            'stroke-width="13" stroke-linecap="butt" stroke-dasharray="' +
            (c * share).toFixed(1) + " " + c.toFixed(1) + '" transform="rotate(-90 56 56)"/>' +
        "</svg>" +
        '<div class="val display">' + g.lineages.toLocaleString() + "</div>" +
        '<div class="lab sci">' + g.key + "</div>" +
        '<div class="sub">' + Math.round(share * 100) + "% of all lineages</div>" +
      "</div>";
    }).join("");
  }

  /* Host taxa reached, per parasite genus. The sets overlap -- a host species can
     carry more than one genus -- so these are bars, not rings: they show reach,
     not shares. Values are read straight off the per-genus payload. */
  var RANKS = [
    { field: "host_species",  label: "Host species" },
    { field: "host_genera",   label: "Host genera" },
    { field: "host_families", label: "Host families" },
    { field: "host_orders",   label: "Host orders" }
  ];
  function drawRanks() {
    document.getElementById("ranks").innerHTML = RANKS.map(function (rank) {
      var max = Math.max.apply(null, GENERA.map(function (g) { return g[rank.field]; }));
      var bars = GENERA.map(function (g) {
        var v = g[rank.field];
        return '<div class="rbar">' +
          '<div class="glab"><span class="sci">' + g.key + '</span>' +
            '<span class="v">' + n(v) + "</span></div>" +
          '<div class="track"><span class="fill" style="width:' + (v / max * 100).toFixed(1) +
            '%;background:var(' + g.varName + ')"></span></div>' +
        "</div>";
      }).join("");
      return '<div class="rank-card"><h4>' + rank.label + "</h4>" +
             '<div class="rank-bars">' + bars + "</div></div>";
    }).join("");
  }

  /* Choropleths: one panel per genus, one hue light-to-dark within each. */
  var BINS = [
    { min: 1,  max: 2,   step: 1 },
    { min: 3,  max: 5,   step: 2 },
    { min: 6,  max: 10,  step: 3 },
    { min: 11, max: 25,  step: 4 },
    { min: 26, max: 1e9, step: 5 }
  ];
  function binFor(n) {
    for (var i = 0; i < BINS.length; i++) if (n >= BINS[i].min && n <= BINS[i].max) return BINS[i].step;
    return 0;
  }
  /* Join the release's per-country counts onto the fixed basemap. The counts are
     keyed by MalAvi's own country spelling; MAP.aliases translates the handful
     that the basemap names differently. Anything that will not join is reported
     by the generator, so a new country in a future release surfaces rather than
     quietly disappearing from the map. */
  function joinCountsToBasemap() {
    var byAtlasName = {};
    var placed = 0, unplaced = 0;
    Object.keys(STATS.country_studies).forEach(function (malaviName) {
      var atlasName = MAP.aliases[malaviName] || malaviName;
      if (MAP.paths[atlasName]) {
        byAtlasName[atlasName] = STATS.country_studies[malaviName];
        placed++;
      } else {
        unplaced++;
      }
    });
    return { counts: byAtlasName, placed: placed, unplaced: unplaced };
  }

  var JOINED = joinCountsToBasemap();

  function drawMaps() {
    document.getElementById("maps").innerHTML = GENERA.map(function (g) {
      var initial = g.key.charAt(0);
      var paths = Object.keys(MAP.paths).map(function (name) {
        var count = (JOINED.counts[name] || {})[initial] || 0;
        var fill = count ? "var(--" + g.ramp + binFor(count) + ")" : "var(--map-none)";
        return '<path d="' + MAP.paths[name] + '" fill="' + fill +
               '" data-country="' + name + '" data-n="' + count + '"></path>';
      }).join("");
      var swatches = [1, 2, 3, 4, 5].map(function (s) {
        return '<i style="background:var(--' + g.ramp + s + ')"></i>';
      }).join("");
      return '<div class="map-panel" data-genus="' + g.key + '">' +
        '<h4 class="sci">' + g.key + "</h4>" +
        '<p class="cap">' + n(g.map_countries) + " countries with records, " +
          n(g.map_countries_shown) + " of them on the map</p>" +
        '<svg viewBox="0 0 ' + MAP.width + " " + MAP.height + '" role="img" aria-label="' +
          g.key + ' studies per country">' + paths + "</svg>" +
        '<div class="scale"><span>1</span>' + swatches + "<span>26+ studies</span></div>" +
        '<div class="map-tip">Hover a country</div>' +
      "</div>";
    }).join("");

    /* Hover readout, per panel. */
    document.getElementById("maps").addEventListener("mouseover", function (e) {
      var p = e.target.closest("path[data-country]");
      if (!p) return;
      var panel = p.closest(".map-panel");
      var n = Number(p.dataset.n);
      panel.querySelector(".map-tip").textContent = n
        ? p.dataset.country + ": " + n + " stud" + (n === 1 ? "y" : "ies")
        : p.dataset.country + ": no records";
    });
    document.getElementById("maps").addEventListener("mouseout", function (e) {
      var panel = e.target.closest(".map-panel");
      if (panel && !panel.contains(e.relatedTarget)) {
        panel.querySelector(".map-tip").textContent = "Hover a country";
      }
    });
  }

  bindStats(JOINED.placed, JOINED.unplaced);
  drawStrip(); drawComposition(); drawDonuts(); drawRanks(); drawMaps();

  /* ----------------------------------------------------------- tables index */
  var GENUS_CLASS = { Plasmodium: "sw-p", Haemoproteus: "sw-h", Leucocytozoon: "sw-l" };

  function escapeHtml(v) {
    return String(v == null ? "" : v).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  /* The table list is driven by STATS.tables -- title, description and row count
     all come from the release. TABLE_INDEX supplies the column spec. `rows`
     starts null and is filled in by fetchRows() the first time the table is
     opened; see openTable(). */
  var TABLES = STATS.tables.map(function (meta) {
    var spec = TABLE_INDEX.tables[meta.id] || { columns: [] };
    return {
      id: meta.id, title: meta.title, description: meta.description,
      group: meta.group, totalRows: meta.rows, columns: spec.columns, rows: null
    };
  }).filter(function (t) { return t.columns.length; });

  /* ------------------------------------------------- queue and contributors */
  /* Both are generated by curation/build_site_feeds.py from real submissions.
     Neither is ever hand-edited, and the contributor board carries only people
     who opted in on the form -- the generator strips everything else. */
  var queueTrack = document.getElementById("queueTrack");
  if (queueTrack) {
    var items = (QUEUE && QUEUE.items) || [];
    var note = document.getElementById("queueNote");
    if (!items.length) {
      queueTrack.style.display = "none";
      if (note) note.textContent =
        "No submissions are in the queue yet. This page will list them as they arrive.";
    } else {
      queueTrack.innerHTML = items.map(function (it) {
        return '<div class="status-row">' +
          '<span class="ref">Submitted ' + escapeHtml(it.submitted) +
            "<small>" + escapeHtml(it.detail) + "</small></span>" +
          '<span class="pill ' + escapeHtml(it.pill) + '">' + escapeHtml(it.status) + "</span>" +
          '<span class="when">' + n(it.n_files) +
            (it.n_files === 1 ? " file" : " files") + "</span>" +
          "</div>";
      }).join("");
      if (note) note.textContent =
        n(items.length) + (items.length === 1 ? " submission" : " submissions") +
        " awaiting curation. Every one is reviewed by a curator before anything enters the database.";
    }
  }

  var board = document.getElementById("contribBoard");
  if (board) {
    var people = (CONTRIBUTORS && CONTRIBUTORS.contributors) || [];
    var cnote = document.getElementById("contribNote");
    if (!people.length) {
      board.style.display = "none";
      if (cnote) cnote.textContent = "The board fills in once the new submission route opens.";
    } else {
      board.innerHTML = people.map(function (p, i) {
        return '<div class="board-row">' +
          '<span class="rank display">' + (i + 1) + "</span>" +
          '<span class="who">' + escapeHtml(p.name) +
            (p.institution ? "<small>" + escapeHtml(p.institution) + "</small>" : "") +
          "</span>" +
          '<span class="metric">' + n(p.lineages) + "<small>Lineages</small></span>" +
          '<span class="metric">' + n(p.records) + "<small>Records</small></span>" +
          "</div>";
      }).join("");
      if (cnote) cnote.textContent = "Updated with every release. Listing is opt-in.";
    }
  }

  /* ------------------------------------------------- downloads and reports */
  /* Every generated file is named <stem>_<release>.<ext>, so the release string
     is the only thing needed to build a link. Nothing here is hard-coded: bump
     the release, re-run the export scripts, and the links follow. */
  var RELEASE = STATS.release;

  /* The one place a table's download URLs are built. Both the table index and
     the open-table toolbar call this, so the two sets of buttons cannot get out
     of step with each other or with the generated filenames. */
  function tableDownloadHref(tableId, ext) {
    return "assets/downloads/tables/" + tableId + "_" + RELEASE + "." + ext;
  }

  function tindexRow(t) {
    return '<div class="tindex-row">' +
      '<div class="tindex-main"><a data-open="' + t.id + '">' + escapeHtml(t.title) + "</a>" +
        "<p>" + escapeHtml(t.description) + "</p></div>" +
      '<span class="rowcount">' + n(t.totalRows) + " rows</span>" +
      '<div class="tindex-actions">' +
        '<button class="mini" data-open="' + t.id + '">Open</button>' +
        '<a class="mini" href="' + tableDownloadHref(t.id, "csv") + '" download>CSV</a>' +
        '<a class="mini" href="' + tableDownloadHref(t.id, "xlsx") + '" download>Excel</a>' +
      "</div></div>";
  }

  /* Two blocks: the release's own tables, then anything built on top of MalAvi.
     Which block a table lands in comes from its `group` in the payload, not from
     a list kept here -- a table added upstream lands in the right place without
     this file being touched. Anything without a group is treated as release
     data, which is what every table was before the distinction existed. */
  function isDerived(t) { return t.group === "derived"; }
  document.getElementById("tindex").innerHTML =
    TABLES.filter(function (t) { return !isDerived(t); }).map(tindexRow).join("");

  var derived = TABLES.filter(isDerived);
  var derivedBlock = document.getElementById("tindexDerivedBlock");
  if (!derived.length) {
    derivedBlock.style.display = "none";
  } else {
    document.getElementById("tindexDerived").innerHTML = derived.map(tindexRow).join("");
  }

  var alignmentLink = document.getElementById("dlAlignment");
  if (alignmentLink) {
    alignmentLink.href = "assets/downloads/malavi_alignment_" + RELEASE + ".fasta";
  }
  var everythingLink = document.getElementById("dlEverything");
  if (everythingLink) {
    everythingLink.href = "assets/downloads/malavi_" + RELEASE + ".zip";
  }

  /* ------------------------------------------------------ known data issues */
  /* The About page's issues list comes from STATS.data_issues, which
     export/build_site_stats.R captures from malaviR::malavi_issues() for the
     pinned release. malavi_issues() re-derives each issue from the release it
     has loaded and writes its sentence from that result, so the text here is
     always about the release actually published -- the same guarantee every
     other figure on this page has, and the reason none of it is typed into the
     markup. A release with nothing recorded leaves the card hidden. */
  (function () {
    var card = document.getElementById("dataIssuesCard");
    var list = document.getElementById("dataIssues");
    if (!card || !list) return;

    var issues = STATS.data_issues || [];
    if (!issues.length) return;

    list.innerHTML = issues.map(function (issue) {
      return "<li><b>" + escapeHtml(issue.title) + "</b>" +
             escapeHtml(issue.text) + "</li>";
    }).join("");
    card.hidden = false;
  })();

  /* The report cards are rendered from reports.json, written by
     export/build_reports.R alongside the CSVs it generates, so the row counts
     shown here cannot drift from the files they describe. */
  Array.prototype.forEach.call(document.querySelectorAll("[data-reports]"), function (host) {
    host.innerHTML = REPORTS.reports.map(function (r) {
      return '<a href="assets/reports/' + encodeURIComponent(r.file) + '" download>' +
             '<span class="nm">' + escapeHtml(r.title) + "</span>" +
             '<span class="ds">' + escapeHtml(r.description) + "</span>" +
             '<span class="fm">CSV · ' + n(r.rows) + " rows</span></a>";
    }).join("");
  });

  /* ------------------------------------------------------------ table view */
  /* colIndex maps a column's key to its position in a row array; buildHead()
     rebuilds it whenever a table is opened. */
  var state = { table: null, page: 0, size: 25, filters: {}, colIndex: {} };
  var indexEl = document.getElementById("tablesIndex");
  var viewEl = document.getElementById("tableView");

  /* A table's rows are fetched once per page load and then kept, so paging back
     and forth between tables costs one download each and no more. */
  function fetchRows(table) {
    if (table.rows) return Promise.resolve(table.rows);
    return fetch("assets/data/tables/" + table.id + ".json", REVALIDATE)
      .then(function (r) {
        if (!r.ok) throw new Error("could not load the " + table.title + " table");
        return r.json();
      })
      .then(function (payload) {
        table.rows = payload.rows;
        return table.rows;
      });
  }

  /* One full-width message in the table body: used while a table downloads and
     if the download fails. */
  function tableMessage(text) {
    document.getElementById("tvBody").innerHTML =
      '<tr><td class="empty" colspan="' + state.table.columns.length + '">' +
      escapeHtml(text) + "</td></tr>";
  }

  function openTable(id) {
    var table = TABLES.filter(function (t) { return t.id === id; })[0];
    if (!table) return;
    state.table = table;
    state.page = 0;
    state.filters = {};
    document.getElementById("tvTitle").textContent = table.title;
    document.getElementById("tvDesc").textContent = table.description;
    document.getElementById("tvNote").textContent =
      "All " + n(table.totalRows) + " rows of this table, from release " + RELEASE +
      ", are searched here — the column filters look at every row, not only the " +
      "page on screen.";
    /* Point the two download buttons at this table's generated files. These
       serve the complete table, not what is currently filtered on screen. */
    document.getElementById("dlCsv").href  = tableDownloadHref(table.id, "csv");
    document.getElementById("dlXlsx").href = tableDownloadHref(table.id, "xlsx");
    buildHead();

    /* Show the table view straight away so the click feels immediate, then fill
       in the body once the rows arrive. */
    indexEl.style.display = "none";
    viewEl.style.display = "";
    window.scrollTo({ top: 0, behavior: "instant" });

    if (table.rows) { render(); return; }
    tableMessage("Loading " + n(table.totalRows) + " rows…");
    document.getElementById("tvCount").textContent = "";
    fetchRows(table).then(function () {
      /* The visitor may have opened a different table while this one was in
         flight; only draw if this is still the one on screen. */
      if (state.table === table) render();
    }).catch(function (err) {
      if (state.table === table) tableMessage(err.message + ". Reload the page to try again.");
    });
  }

  function buildHead() {
    var cols = state.table.columns;
    /* A row is an array of cells in column order, so a filter keyed by column
       has to know that column's position. Built once per table rather than
       looked up per cell on every keystroke. */
    state.colIndex = {};
    cols.forEach(function (c, i) { state.colIndex[c.key] = i; });
    document.getElementById("tvHead").innerHTML =
      "<tr>" + cols.map(function (c) { return "<th>" + escapeHtml(c.label) + "</th>"; }).join("") + "</tr>" +
      '<tr class="colfilters">' + cols.map(function (c) {
        return '<th><input type="search" data-col="' + c.key +
               '" placeholder="filter" aria-label="Filter by ' + escapeHtml(c.label) + '"></th>';
      }).join("") + "</tr>";
  }

  /* Empty until the table's rows have downloaded; every caller treats that as
     "no rows yet" rather than failing. */
  function filteredRows() {
    var rows = state.table.rows || [];
    var active = Object.keys(state.filters).filter(function (k) { return state.filters[k]; });
    if (!active.length) return rows;
    return rows.filter(function (row) {
      return active.every(function (key) {
        var v = row[state.colIndex[key]];
        return String(v == null ? "" : v).toLowerCase().indexOf(state.filters[key]) !== -1;
      });
    });
  }

  function cellHtml(col, i, row) {
    var v = row[i];
    if (col.type === "genus") {
      return '<td><span class="genus-pill"><i class="' + (GENUS_CLASS[v] || "") + '"></i>' +
             escapeHtml(v) + "</span></td>";
    }
    var cls = col.type === "key" ? "key" : col.type === "num" ? "num"
            : col.type === "wrap" ? "wrap" : col.type === "sci" ? "sci"
            : col.type === "seq" ? "seq" : "";
    return "<td" + (cls ? ' class="' + cls + '"' : "") + ">" + escapeHtml(v) + "</td>";
  }

  function pagerHtml(totalPages) {
    return '<button class="pgFirst" ' + (state.page === 0 ? "disabled" : "") + ">First</button>" +
           '<button class="pgPrev" '  + (state.page === 0 ? "disabled" : "") + ">Prev</button>" +
           '<span class="pos">Page ' + (state.page + 1) + " of " + Math.max(totalPages, 1) + "</span>" +
           '<button class="pgNext" ' + (state.page >= totalPages - 1 ? "disabled" : "") + ">Next</button>" +
           '<button class="pgLast" ' + (state.page >= totalPages - 1 ? "disabled" : "") + ">Last</button>";
  }

  function render() {
    /* The rows are still downloading. tableMessage() owns the table body until
       they land, and openTable() re-renders once they do -- including any
       filters typed while waiting. */
    if (!state.table || !state.table.rows) return;

    var cols = state.table.columns;
    var rows = filteredRows();
    var totalPages = Math.ceil(rows.length / state.size) || 1;
    if (state.page > totalPages - 1) state.page = totalPages - 1;
    var start = state.page * state.size;
    var slice = rows.slice(start, start + state.size);

    document.getElementById("tvBody").innerHTML = slice.length
      ? slice.map(function (row) {
          return "<tr>" + cols.map(function (c, i) { return cellHtml(c, i, row); }).join("") + "</tr>";
        }).join("")
      : '<tr><td class="empty" colspan="' + cols.length +
        '">No rows match those filters. Clear one to widen the search.</td></tr>';

    document.getElementById("tvCount").textContent =
      rows.length.toLocaleString() + " matching row" + (rows.length === 1 ? "" : "s") +
      (slice.length ? " · showing " + (start + 1) + "–" + (start + slice.length) : "");

    document.getElementById("pagerTop").innerHTML = pagerHtml(totalPages);
    document.getElementById("pagerBottom").innerHTML = pagerHtml(totalPages);
  }

  document.addEventListener("click", function (e) {
    var open = e.target.closest("[data-open]");
    if (open) { e.preventDefault(); openTable(open.dataset.open); return; }

    var page = e.target.closest(".pager button");
    if (page && state.table) {
      var totalPages = Math.ceil(filteredRows().length / state.size) || 1;
      if (page.classList.contains("pgFirst")) state.page = 0;
      else if (page.classList.contains("pgPrev")) state.page = Math.max(0, state.page - 1);
      else if (page.classList.contains("pgNext")) state.page = Math.min(totalPages - 1, state.page + 1);
      else if (page.classList.contains("pgLast")) state.page = totalPages - 1;
      render();
    }
  });

  document.getElementById("backToIndex").addEventListener("click", function () {
    viewEl.style.display = "none";
    indexEl.style.display = "";
    window.scrollTo({ top: 0, behavior: "instant" });
  });

  document.getElementById("pageSize").addEventListener("change", function (e) {
    state.size = Number(e.target.value);
    state.page = 0;
    render();
  });

  document.getElementById("tvHead").addEventListener("input", function (e) {
    var input = e.target.closest("input[data-col]");
    if (!input) return;
    state.filters[input.dataset.col] = input.value.trim().toLowerCase();
    state.page = 0;
    render();
  });

  document.getElementById("clearFilters").addEventListener("click", function () {
    state.filters = {};
    Array.prototype.forEach.call(
      document.querySelectorAll("#tvHead input"), function (i) { i.value = ""; });
    state.page = 0;
    render();
  });

  /* --------------------------------------------------------- the checker
     The matching logic lives in sequence-check.mjs, which is tested against
     every sequence in the release (assets/js/tests/test_sequence_check.mjs).
     Nothing about identity is decided in this file.

     The reference index is ~3 MB uncompressed (about 200 KB over the wire) and
     is only needed by people who actually use the checker, so it is fetched on
     first use rather than on page load. */
  let checkerPromise = null;

  function loadChecker() {
    if (!checkerPromise) {
      checkerPromise = Promise.all([
        import("./sequence-check.mjs"),
        fetch("assets/data/lineage_sequences.json").then(function (r) {
          if (!r.ok) throw new Error("could not load the lineage index");
          return r.json();
        })
      ]).then(function (parts) {
        var module = parts[0];
        return { module: module, index: module.buildIndex(parts[1]) };
      });
    }
    return checkerPromise;
  }

  var MARKS = { known: "\u2713", "new": "\u25c6", stop: "\u2715", unknown: "\u25c6" };

  /* The stylesheet paints verdicts in three washes -- ok, warn, stop -- and the
     four verdicts the checker returns map onto them. Writing the verdict name
     straight into the class left v-known, v-new and v-unknown unstyled, so
     three of the four answers came out unpainted. */
  var VERDICT_CLASS = { known: "ok", "new": "warn", stop: "stop", unknown: "warn" };

  /* The naming box. Only shown for a probable new lineage, because it is the
     only case where a name is needed at all. The host species is the one thing
     the sequence cannot tell us, so it has to be asked for. */
  function namingPanel(outId) {
    return '' +
      '<div class="naming">' +
        '<label class="eyebrow" for="' + outId + '-host">Host species this came from</label>' +
        '<div class="btn-row">' +
          '<input id="' + outId + '-host" type="text" spellcheck="false" autocomplete="off" ' +
            'placeholder="Turdus migratorius">' +
          '<button class="btn ghost" type="button" data-name-suggest="' + outId + '-host" ' +
            'data-out="' + outId + '-name">Check the name</button>' +
        '</div>' +
        '<p class="fine">A new lineage takes \u201ca 5-6 letter acronym based on the scientific name ' +
          'of the first encountered host species followed by a two-digit number\u201d. Both the ' +
          'five- and six-letter forms are in use, so this shows you the numbers each has ' +
          'already taken rather than picking for you. A curator confirms the final name.</p>' +
        '<div class="naming-out" id="' + outId + '-name"></div>' +
      '</div>';
  }

  function renderResult(outId, result) {
    var box = document.getElementById(outId);
    var checks = (result.checks || []).map(function (c) {
      return '<li><span class="tag t-' + c.state + '">' + c.label + "</span><span>" +
             c.text + "</span></li>";
    });
    var html = '<div class="verdict v-' + (VERDICT_CLASS[result.verdict] || "warn") +
      '"><span class="mark">' +
      (MARKS[result.verdict] || "") + '</span><div><h4>' + result.title + "</h4><p>" +
      result.message + "</p></div></div>";
    if (checks.length) html += '<ul class="checklist">' + checks.join("") + "</ul>";
    if (result.naming) html += namingPanel(outId);
    box.innerHTML = html;
    box.classList.add("show");
  }

  function renderMessage(outId, verdict, title, message) {
    renderResult(outId, { verdict: verdict, title: title, message: message, checks: [] });
  }

  /* The host box is a single-line field, so Enter should submit it. */
  document.addEventListener("keydown", function (e) {
    if (e.key !== "Enter") return;
    var field = e.target.closest("input[id$='-host']");
    if (!field) return;
    var button = document.querySelector('[data-name-suggest="' + field.id + '"]');
    if (button) { e.preventDefault(); button.click(); }
  });

  document.addEventListener("click", function (e) {
    var runner = e.target.closest("[data-check]");
    if (runner) {
      var raw = document.getElementById(runner.dataset.check).value;
      var out = runner.dataset.out;
      renderMessage(out, "unknown", "Checking\u2026",
        "Loading the lineage index. This happens once per visit.");
      loadChecker().then(function (checker) {
        renderResult(out, checker.module.checkSequence(checker.index, raw));
      }).catch(function (err) {
        renderMessage(out, "stop", "Could not run the checks",
          "The lineage index did not load (" + err.message + "). Please reload the page, " +
          "or send us the sequence and we will check it for you.");
      });
      return;
    }

    /* Naming: the submitter types the host species, we read the lineage names
       already in the release and report which numbers that host's acronym has
       used. Nothing is assigned and nothing is sent anywhere. */
    var namer = e.target.closest("[data-name-suggest]");
    if (namer) {
      var host = document.getElementById(namer.dataset.nameSuggest).value;
      var nameBox = document.getElementById(namer.dataset.out);
      nameBox.innerHTML = "<p class=\"fine\">Checking the names in use…</p>";
      loadChecker().then(function (checker) {
        var suggestion = checker.module.suggestLineageName(checker.index, host, RESERVED, BIRDS);
        if (!suggestion.ok) {
          nameBox.innerHTML = '<p class="fine">' + suggestion.message + "</p>";
          return;
        }
        var rows = suggestion.options.map(function (option) {
          /* A name held by a submission in the queue is not free, so say who is
             ahead by date rather than just skipping the number. */
          var held = option.claims.map(function (c) {
            return escapeHtml(c.name) + " (claimed " + escapeHtml(c.claimed) + ")";
          }).join(", ");
          return '<li><span class="tag t-' + (option.taken ? "pass" : "warn") + '">' +
            option.acronym + '</span><span><b>' + option.proposal + '</b> — ' +
            (option.taken
              ? option.taken + (option.taken === 1
                  ? " lineage already uses this acronym, "
                  : " lineages already use this acronym, ") +
                "up to " + option.highest + "."
              : "no lineage uses this acronym yet.") +
            (held
              ? " Already claimed by a submission ahead of you: " + held +
                ". Priority goes by the date a submission arrives."
              : "") +
            "</span></li>";
        }).join("");
        /* What the avian checklist makes of the name. Reported, never enforced:
           taxonomy moves, the checklist is a dated snapshot, and a submitter who
           has found a bird it has not caught up with is right more often than the
           file is. So every branch below still shows the acronyms. */
        var tax = suggestion.taxonomy || { status: "unchecked" };
        var taxNote = "";
        if (tax.status === "synonym") {
          taxNote = '<p class="fine">The current name for <i>' + escapeHtml(tax.name) +
            '</i> is <i>' + escapeHtml(tax.current) + '</i>. Both are offered below — ' +
            'use whichever your paper will use, since the lineage name should match it.</p>';
        } else if (tax.status === "genus-only") {
          taxNote = '<p class="fine"><b>' + escapeHtml(tax.genus) + '</b> is a bird genus (' +
            escapeHtml(tax.family || "family unknown") + '), but <b><i>' + escapeHtml(tax.name) +
            '</i> is not one of its species in the eBird/Clements checklist.</b> Worth ' +
            'checking the spelling. ' + CHECKLIST_BEHIND_NOTE + '</p>';
        } else if (tax.status === "unknown") {
          taxNote = '<p class="fine"><b><i>' + escapeHtml(tax.name) + '</i> is not in the ' +
            'eBird/Clements checklist, and neither is the genus.</b> Please check the ' +
            'spelling: a lineage acronym is built from the host name and ends up in ' +
            'your paper and in GenBank, so a typo here is hard to undo. ' +
            CHECKLIST_BEHIND_NOTE + '</p>';
        }

        nameBox.innerHTML = taxNote +
          '<p class="fine">For <i>' + suggestion.host + '</i>' +
          (tax.status === "accepted" && tax.family
            ? ' (' + escapeHtml(tax.family) + ')'
            : "") +
          (suggestion.inUse
            ? ", following the acronym MalAvi already uses for this host:"
            : ". Neither acronym is in use yet, so both are open — note that a lineage " +
              "from this host may still exist under one of the older, less regular names:") +
          '</p><ul class="checklist">' + rows + "</ul>" +
          '<p class="fine">Checked against release ' + escapeHtml(STATS.release) +
          (BIRDS ? ' and the eBird/Clements checklist' +
            (BIRDS.clootl_year ? ' (' + escapeHtml(String(BIRDS.clootl_year)) + ')' : '')
            : '') +
          (RESERVED
            ? " and against names claimed by submissions received up to " +
              escapeHtml((RESERVED.generated || "").slice(0, 10)) +
              ". A submission that arrived after that is not shown here."
            : ". Submissions still in the queue could not be checked.") +
          " Send the sequence, the host and the name you prefer with the " +
          'submission form and a curator will confirm it. Please wait for that before ' +
          'depositing in GenBank — the same name has to end up in all three places.</p>';
      }).catch(function (err) {
        nameBox.innerHTML = '<p class="fine">Could not read the lineage names (' +
          err.message + ").</p>";
      });
      return;
    }

    var demo = e.target.closest("[data-demo]");
    if (demo) {
      /* A real lineage sequence with two point changes, so the example lands on
         the interesting answer: a plausible new lineage. Taken from the loaded
         index so it is always a genuine sequence from the current release. */
      var target = document.getElementById(demo.dataset.demo);
      target.value = "Loading an example\u2026";
      loadChecker().then(function (checker) {
        var entry = checker.index.entries.find(function (x) {
          return x.ungapped.length === checker.index.windowLength;
        }) || checker.index.entries[0];
        var seed = entry.ungapped;
        seed = seed.slice(0, 120) + (seed[120] === "A" ? "G" : "A") +
               seed.slice(121, 300) + (seed[300] === "T" ? "C" : "T") + seed.slice(301);
        target.value = (seed.match(/.{1,60}/g) || []).join("\n");
      }).catch(function () {
        target.value = "";
      });
    }
  });
})();
